import{buildShip}from'./scene.mjs?v=8j';import{profile,exteriorEntry}from'./spatial.mjs?v=8j';
export const HULL_SCALE=.6;
const raw=buildShip(),faces=[];
for(let i=0;i<raw.length;i+=30)faces.push({a:Array.from(raw.slice(i,i+3),x=>x*HULL_SCALE),b:Array.from(raw.slice(i+10,i+13),x=>x*HULL_SCALE),c:Array.from(raw.slice(i+20,i+23),x=>x*HULL_SCALE),color:Array.from(raw.slice(i+6,i+9)),glow:raw[i+9]});
const nodes=[],ordered=[];
function build(items){const index=nodes.length,node={min:[Infinity,Infinity,Infinity],max:[-Infinity,-Infinity,-Infinity]};nodes.push(node);for(const f of items)for(const p of[f.a,f.b,f.c])for(let j=0;j<3;j++){node.min[j]=Math.min(node.min[j],p[j]);node.max[j]=Math.max(node.max[j],p[j]);}if(items.length<=4){node.first=ordered.length;node.count=items.length;ordered.push(...items);}else{let axis=0;for(let j=1;j<3;j++)if(node.max[j]-node.min[j]>node.max[axis]-node.min[axis])axis=j;items.sort((a,b)=>(a.a[axis]+a.b[axis]+a.c[axis])-(b.a[axis]+b.b[axis]+b.c[axis]));const m=items.length>>1;node.left=build(items.slice(0,m));node.right=build(items.slice(m));}node.escape=nodes.length;return index;}
build(faces);export const hullFaces=ordered,hullNodes=nodes,HULL_NODE_VECTORS=nodes.length*3,HULL_FACE_VECTORS=ordered.length*4;
export const HULL_RADIUS=Math.max(...ordered.flatMap(f=>[f.a,f.b,f.c].map(p=>Math.hypot(...p))));
export const hullUniform=new Float32Array((HULL_NODE_VECTORS+HULL_FACE_VECTORS)*4);
nodes.forEach((n,i)=>{hullUniform.set([...n.min,n.count?-(n.first+1):n.left,...n.max,n.count??n.right,n.escape,0,0,0],i*12);});ordered.forEach((f,i)=>hullUniform.set([...f.a,0,...f.b,0,...f.c,0,...f.color,f.glow],HULL_NODE_VECTORS*4+i*16));
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0),sub=(a,b)=>a.map((x,i)=>x-b[i]),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
export function triangleSegment(origin,delta,face){const e1=sub(face.b,face.a),e2=sub(face.c,face.a),p=cross(delta,e2),det=dot(e1,p);if(Math.abs(det)<1e-12)return Infinity;const s=sub(origin,face.a),u=dot(s,p)/det;if(u<0||u>1)return Infinity;const q=cross(s,e1),v=dot(delta,q)/det;if(v<0||u+v>1)return Infinity;const t=dot(e2,q)/det;return t>1e-7&&t<=1?t:Infinity;}
export function intersectHull(origin,delta,brute=false){let t=Infinity,face=-1;const test=i=>{const hit=triangleSegment(origin,delta,ordered[i]);if(hit<t){t=hit;face=i;}};if(brute){ordered.forEach((_,i)=>test(i));return{t,face};}const stack=[0];while(stack.length){const n=nodes[stack.pop()];let lo=0,hi=Math.min(1,t);for(let j=0;j<3;j++){if(Math.abs(delta[j])<1e-14){if(origin[j]<n.min[j]-.00001||origin[j]>n.max[j]+.00001){hi=-1;break;}}else{const a=(n.min[j]-.00001-origin[j])/delta[j],b=(n.max[j]+.00001-origin[j])/delta[j];lo=Math.max(lo,Math.min(a,b));hi=Math.min(hi,Math.max(a,b));}}if(hi<lo)continue;if(n.count)for(let i=n.first;i<n.first+n.count;i++)test(i);else stack.push(n.left,n.right);}return{t,face};}
export function hullFrequency(v,point,K){const b=v*(1-profile(Math.hypot(...point)).f);return K>0&&Math.abs(b)<1?Math.sqrt(1-b*b)/K:0;}
function derivative(q,v){const r=Math.hypot(...q.p),f=profile(r),g=q.p.map(x=>r>1e-9?-v*f.df*x/r:0),ng=dot(q.n,g);return{p:q.n.map((x,i)=>x+(i===2?v*(1-f.f):0)),n:g.map((x,i)=>-q.n[2]*(x-q.n[i]*ng)),l:-q.n[2]*ng};}
const add=(q,k,h)=>({p:q.p.map((x,i)=>x+h*k.p[i]),n:q.n.map((x,i)=>x+h*k.n[i]),l:q.l+h*k.l,t:q.t});
export function advanceShipRay(q,h,v){const a=derivative(q,v),b=derivative(add(q,a,h/2),v),c=derivative(add(q,b,h/2),v),d=derivative(add(q,c,h),v),next={p:q.p.map((x,i)=>x+h*(a.p[i]+2*b.p[i]+2*c.p[i]+d.p[i])/6),n:q.n.map((x,i)=>x+h*(a.n[i]+2*b.n[i]+2*c.n[i]+d.n[i])/6),l:q.l+h*(a.l+2*b.l+2*c.l+d.l)/6,t:q.t+h};const m=Math.hypot(...next.n);next.n=next.n.map(x=>x/m);return next;}
export function traceShipRay(origin,direction,v,{stepScale=1,maxSteps=4096}={}){const norm=Math.hypot(...direction),n=direction.map(x=>x/norm),K=1+v*(1-profile(Math.hypot(...origin)).f)*n[2];let q={p:[...origin],n,l:0,t:0};
 if(v<.00001){const reach=Math.max(400,Math.hypot(...origin)*2+2),hit=intersectHull(origin,n.map(x=>x*reach));if(hit.face>=0)return{...q,p:origin.map((x,i)=>x+n[i]*reach*hit.t),t:reach*hit.t,face:hit.face,logFrequency:0,K,escaped:false};return{...q,face:-1,logFrequency:0,K,escaped:true};}
 const entry=exteriorEntry(origin,n,v);if(entry<0)return{...q,face:-1,logFrequency:0,K,escaped:true};if(entry>0){q.t=entry+1e-4/(1+v);q.p=q.p.map((x,i)=>x+(n[i]+(i===2?v:0))*q.t);}const end=q.t+48;
 for(let i=0;i<maxSteps&&q.t<end&&q.l<=14;i++){const r=Math.hypot(...q.p),f=profile(r),h=Math.min(.024*stepScale,.035*stepScale/(1+Math.abs(v*(1-f.f))+Math.abs(v*f.df)),r<HULL_RADIUS+.07?Math.sqrt(.000016/Math.max(.000001,Math.abs(v*f.df)*(2+Math.abs(v*(1-f.f)))))*stepScale:Infinity,end-q.t),next=advanceShipRay(q,h,v),delta=sub(next.p,q.p);if(K>0&&Math.min(Math.hypot(...q.p),Math.hypot(...next.p))<HULL_RADIUS+.04){const hit=intersectHull(q.p,delta);if(hit.face>=0){const face=ordered[hit.face],normal=cross(sub(face.b,face.a),sub(face.c,face.a));let fraction=hit.t,event;for(let j=0;j<3;j++){event=advanceShipRay(q,h*fraction,v);const den=h*dot(normal,derivative(event,v).p);if(Math.abs(den)>1e-14)fraction=Math.max(0,Math.min(1,fraction-dot(normal,sub(event.p,face.a))/den));}event=advanceShipRay(q,h*fraction,v);return{...event,face:hit.face,logFrequency:Math.log(hullFrequency(v,event.p,K)),K,escaped:false};}}q=next;if(Math.hypot(...q.p)>=3.2)return{...q,face:-1,logFrequency:-q.l,K,escaped:true};}
 return{...q,face:-1,logFrequency:-q.l,K,escaped:false,t:-1};
}
